// El Vector Store devuelve un ítem por cada pedazo que guardó. Los contamos para la página final.
const archivo = $('Subir documento').first().json.archivo ?? {};
const pedazos = $input.all().length;
return [{
  json: {
    pedazos,
    pedazos_texto: pedazos === 1 ? '1 pedazo' : `${pedazos} pedazos`,
    archivo: archivo.filename ?? archivo.fileName ?? 'tu archivo',
  },
}];
